import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec3, vec4, float, mix, uniform, positionLocal, clamp, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'photo-hero-composite';

  const position = config.position || [0, 0, 0];
  const rotation = config.rotation || [0, 0, 0];
  const scale = config.scale || [1, 1, 1];
  group.position.set(...position);
  group.rotation.set(...rotation);
  group.scale.set(...scale);

  const PLATE_W = 4.0;
  const PLATE_H = 2.5;

  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/parallax-stack.png';
  const depthUrl = config.depthMapUrl || '/prism-mock/home/nodes/parallax-stack.depth.png';

  const colorMap = ctx.textureLoader.load(imageUrl);
  colorMap.colorSpace = THREE.SRGBColorSpace;
  const depthMap = ctx.textureLoader.load(depthUrl);

  const colorTex = texture(colorMap, uv());
  const depthTex = texture(depthMap, uv());

  const amplitude = uniform(0.18);
  const scrollOffset = uniform(0.0);

  const displaced = positionLocal.add(
    vec3(0.0, 0.0, depthTex.r.sub(0.5).mul(amplitude).add(scrollOffset.mul(depthTex.r).mul(0.28)))
  );

  // filmic grade: lift blacks, shoulder highlights, contrast, desaturate but preserve red
  const lifted = mix(vec3(0.051, 0.051, 0.071), colorTex.rgb, float(0.94));
  const contrasted = lifted.sub(0.5).mul(1.12).add(0.5);
  const luma = contrasted.r.mul(0.299).add(contrasted.g.mul(0.587)).add(contrasted.b.mul(0.114));
  const desat = mix(contrasted, vec3(luma, luma, luma), float(0.08));
  const gradedRgb = vec3(contrasted.r, desat.g, desat.b);

  // rim light along silhouette using depth gradient approximation via uv offset sampling
  const depthRight = texture(depthMap, uv().add(vec2(0.02, 0.0))).r;
  const rim = clamp(depthTex.r.sub(depthRight).abs().mul(6.0), 0.0, 1.0);
  const rimColor = vec3(0.909, 0.925, 0.949).mul(rim).mul(0.6);

  // bottom scrim gradient
  const gradT = smoothstep(0.0, 0.55, uv().y.oneMinus());
  const scrimColor = vec3(0.043, 0.043, 0.063);
  const scrimAlpha = mix(0.0, 0.92, gradT);
  const finalRgb = mix(gradedRgb.add(rimColor), scrimColor, scrimAlpha);

  const plateOpacity = uniform(0.0);
  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = vec4(finalRgb, 1.0);
  material.opacityNode = plateOpacity;
  material.transparent = true;
  material.positionNode = displaced;

  const geometry = new THREE.PlaneGeometry(PLATE_W, PLATE_H, 64, 64);
  const plate = new THREE.Mesh(geometry, material);
  plate.name = 'plate-mesh';
  group.add(plate);

  // accent hairline bar
  const hairlineMat = new THREE.MeshBasicNodeMaterial();
  hairlineMat.colorNode = vec4(1.0, 0.165, 0.22, 1.0);
  hairlineMat.transparent = true;
  const hairlineOpacity = uniform(1.0);
  hairlineMat.opacityNode = hairlineOpacity;
  const hairline = new THREE.Mesh(new THREE.PlaneGeometry(0.75, 0.02), hairlineMat);

  // caption block
  const captionGroup = new THREE.Group();
  captionGroup.name = 'caption-block';

  const kickerMesh = createTextMesh({
    text: 'NOVA ATELIER / GENEVA',
    font: 'JetBrains Mono',
    fontWeight: 700,
    fontSize: 0.09,
    letterSpacing: 0.12,
    color: '#e8ecf2',
    fontAtlas: ctx.fontAtlas,
  });

  const headlineMesh = createTextMesh({
    text: 'Time, Machined.',
    font: 'Lora',
    fontWeight: 600,
    fontSize: 0.34,
    letterSpacing: -0.01,
    color: '#e8ecf2',
    fontAtlas: ctx.fontAtlas,
  });

  const bodyMesh = createTextMesh({
    text: 'Every case begins as a single billet of 904L steel.',
    font: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 0.13,
    letterSpacing: 0,
    color: '#e8ecf2',
    fontAtlas: ctx.fontAtlas,
  });

  const captionMesh = createTextMesh({
    text: 'CALIBRE NA-01 / 72 HOUR RESERVE',
    font: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 0.09,
    letterSpacing: 0.12,
    color: '#e8ecf2',
    fontAtlas: ctx.fontAtlas,
  });

  const PAD = 0.5;
  const baseX = -PLATE_W / 2 + PAD;
  let cursorY = -PLATE_H / 2 + PAD;

  captionMesh.position.set(baseX, cursorY, 0.02);
  cursorY += 0.09 * 1.4 + 0.25;
  bodyMesh.position.set(baseX, cursorY, 0.02);
  cursorY += 0.13 * 1.5 + 0.25;
  hairline.position.set(baseX + 0.375, cursorY, 0.02);
  cursorY += 0.25;
  headlineMesh.position.set(baseX, cursorY, 0.02);
  cursorY += 0.34 * 1.1 + 0.25;
  kickerMesh.position.set(baseX, cursorY, 0.02);

  captionGroup.add(kickerMesh, headlineMesh, hairline, bodyMesh, captionMesh);
  captionGroup.position.y -= 0.4;
  group.add(captionGroup);

  // primitives
  const timelines = [];
  const primitives = config.cinematicPrimitives || [];
  primitives.forEach((prim) => {
    const fn = ctx.primitives[prim.name];
    if (fn) {
      const result = fn(plate, { ...prim.params, onScroll: (v) => { scrollOffset.value = v; } });
      if (result && result.timeline) timelines.push(result.timeline);
    }
  });

  // entrance animations
  const plateTl = gsap.timeline();
  plateTl.to(plateOpacity, {
    value: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });
  timelines.push(plateTl);

  captionGroup.position.y -= 0.0;
  const captionTl = gsap.timeline({ delay: 0.12 });
  captionTl.to(captionGroup.position, {
    y: captionGroup.position.y + 0.4,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  });
  timelines.push(captionTl);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl && tl.kill && tl.kill());
    geometry.dispose();
    material.dispose();
    hairlineMat.dispose();
    hairline.geometry.dispose();
    colorMap.dispose();
    depthMap.dispose();
    [kickerMesh, headlineMesh, bodyMesh, captionMesh].forEach((m) => {
      if (m.geometry) m.geometry.dispose();
      if (m.material) m.material.dispose();
    });
  };

  return group;
}
